import sys, os, json, csv, gzip, io, re
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.splitlines() if l.strip() != '']


def to_ts(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_ts(naive, zone, fold=0):
    return to_ts(naive.replace(tzinfo=zone, fold=fold))


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def std_offset(zone, ts):
    dt = datetime.fromtimestamp(ts, UTC).astimezone(zone)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


# ---- format readers: yield (id, emp, dir, ts) ----
def read_abbr(text, zone):
    header = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Record' in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]]
        m = re.fullmatch(r'(\d+):(\d+):(\d+)\s*([AaPp][Mm])?', g('Time'))
        h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if m.group(4):
            pm = m.group(4).upper() == 'PM'
            h = h % 12 + (12 if pm else 0)
        mo, d, y = g('Date').split('/')
        naive = datetime(int(y), int(mo), int(d), h, mi, s)
        fold = 1 if g('Zone').upper().endswith('ST') else 0
        yield g('Record'), g('Badge'), g('Punch').upper(), local_to_ts(naive, zone, fold)


def read_epoch(text, zone):
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            ts = int(o['epoch_ms'] // 1000)
            yield str(o['punch_id']), o['employee'], o['direction'].upper(), ts
        else:
            if 'ts_ms' in o:
                ts = int(o['ts_ms'] // 1000)
            else:
                ts = int(o['ts'] // 1)
            yield str(o['id']), o['emp'], o['dir'].upper(), ts


def read_offset(text, zone):
    rows = csv.reader(lines_of(text), delimiter=';')
    header = None
    for row in rows:
        if header is None:
            header = {n.strip(): i for i, n in enumerate(row)}
            continue
        g = lambda n: row[header[n]].strip()
        d = 'IN' if g('event') == 'clock_in' else 'OUT'
        yield g('punch_id'), g('employee'), d, to_ts(parse_iso(g('timestamp')))


def read_legacy(text, zone):
    off = None
    for l in text.splitlines():
        if not l.strip():
            continue
        t = l[0]
        if t == 'H':
            m = re.fullmatch(r'([+-])(\d\d)(\d\d)', l[13:18].strip()) if len(l) > 13 else None
            if m:
                sec = int(m.group(2)) * 3600 + int(m.group(3)) * 60
                off = timedelta(seconds=-sec if m.group(1) == '-' else sec)
            else:
                off = None
        elif t == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = 'IN' if l[15] == 'I' else 'OUT'
            n = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            if off is None:
                approx = to_ts(n.replace(tzinfo=UTC))
                o = std_offset(zone, approx)
                o = std_offset(zone, approx - int(o.total_seconds()))
            else:
                o = off
            ts = to_ts(n.replace(tzinfo=UTC) - o)
            yield pid, 'E' + badge, d, ts


def read_de(text, zone):
    header = None
    for row in csv.reader(lines_of(text), delimiter='\t'):
        row = [c.strip() for c in row]
        if 'Ausweis' in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]]
        dd, mm, yy = g('Datum').split('.')
        hh, mi = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
        fold = 0 if g('Zeitzone').upper() == 'MESZ' else 1
        yield g('Nr'), g('Ausweis'), 'IN' if g('Buchung').upper() == 'K' else 'OUT', local_to_ts(naive, zone, fold)


def read_localcsv(text, zone):
    header = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if header is None:
            header = {n: i for i, n in enumerate(row)}
            continue
        g = lambda n: row[header[n]]
        naive = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        yield g('punch_ref'), g('employee_id'), g('direction').upper(), local_to_ts(naive, zone, 0)


def read_localjsonl(text, zone):
    for l in lines_of(text):
        o = json.loads(l)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        yield str(p['id']), p['badge'], p['type'].upper(), local_to_ts(naive, zone, 0)


READERS = {'abbr-csv': read_abbr, 'epoch-jsonl': read_epoch, 'offset-csv': read_offset,
           'legacy-fixed': read_legacy, 'de-tsv': read_de, 'local-csv': read_localcsv,
           'local-jsonl': read_localjsonl}


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = to_ts(parse_iso(period['corrections_cutoff']))

    def rcsv(name):
        with open(os.path.join(inp, name), encoding='utf-8-sig', newline='') as f:
            return [{k.strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]

    sites = {r['site']: r for r in rcsv('sites.csv')}
    zones = {s: ZoneInfo(r['timezone']) for s, r in sites.items()}
    emps = rcsv('employees.csv')
    emp_home = {e['employee_id']: e['home_site'] for e in emps}
    rates = {}
    for r in rcsv('rates.csv'):
        rates.setdefault(r['employee_id'], []).append((date.fromisoformat(r['effective_from']), Decimal(r['hourly_rate'])))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site,id) -> [emp, dir, ts]
    existed = set()
    for site in sorted(sites):
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        rd = READERS[sites[site]['format']]
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                text = read_text(os.path.join(root, fn))
                for pid, emp, dr, ts in rd(text, zones[site]):
                    k = (site, pid)
                    existed.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                with open(os.path.join(root, fn), 'rb') as f:
                    b = f.read()
                if b[:2] == b'\x1f\x8b':
                    b = gzip.decompress(b)
                t = b.decode('utf-8-sig')
                for r in csv.DictReader(io.StringIO(t, newline='')):
                    r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                    if r.get('correction_id'):
                        corr.append(r)
    corr = [(to_ts(parse_iso(r['issued_at'])), r) for r in corr]
    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]['correction_id']))
    applied = 0
    for _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action']
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = to_ts(parse_iso(r['time']))
                applied += 1
        elif a == 'add':
            if k not in existed and r['site'] in sites:
                existed.add(k)
                punches[k] = [r['employee'], r['type'].upper(), to_ts(parse_iso(r['time']))]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, zone):
        off = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
        r = (ts + off) % 360
        return ts - r if r < 180 else ts + (360 - r)

    def wdate(ts, emp):
        return datetime.fromtimestamp(ts, UTC).astimezone(zones[emp_home[emp]]).date()

    def inper(d):
        return pstart <= d <= pend

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {}
    for e in emp_home:
        shifts = []  # (in_r, out_r, site, workday)
        lst = sorted(byemp.get(e, []))
        kept = []
        last = None
        for p in lst:
            if last is not None and last[4] == p[4] and p[0] - last[0] <= 300:
                if inper(wdate(rnd(p[0], zones[p[2]]), e)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(p)
            last = p
        cur = None
        for p in kept:
            r = rnd(p[0], zones[p[2]])
            if p[4] == 'IN':
                if cur:
                    if inper(wdate(cur[0], e)):
                        exc['open_shifts'] += 1
                cur = (r, p[2])
            else:
                if cur and r - cur[0] <= 16 * 3600:
                    shifts.append((cur[0], r, cur[1], wdate(cur[0], e)))
                    cur = None
                else:
                    if cur:
                        if inper(wdate(cur[0], e)):
                            exc['open_shifts'] += 1
                        cur = None
                    if inper(wdate(r, e)):
                        exc['orphan_outs'] += 1
        if cur and inper(wdate(cur[0], e)):
            exc['open_shifts'] += 1
        shifts = [s for s in shifts if inper(s[3])]
        shifts.sort(key=lambda s: s[0])

        daymin = {}
        weekmin = {}
        tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
        pay = Fraction(0)
        for a, b, site, wd in shifts:
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, zones[site]), paid)
            used = daymin.get(wd, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daymin[wd] = used + paid
            nondaily = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wu = weekmin.get(wk, 0)
            wot = max(0, wu + nondaily - 2400) - max(0, wu - 2400)
            weekmin[wk] = wu + nondaily
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(e, []):
                if ef <= wd:
                    rate = rt
            rate = Fraction(rate if rate is not None else 0)
            pay += rate * (Fraction(reg) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            tot['shifts'] += 1
            tot['paid_minutes'] += paid
            tot['overtime_minutes'] += ot
            tot['night_minutes'] += night
        cents = int((pay * 100 + Fraction(1, 2)) // 1)
        tot['gross_c'] = cents
        res[e] = tot

    def money(c):
        return '%d.%02d' % (c // 100, c % 100)

    out_emps = {}
    T = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=0)
    for e, t in res.items():
        out_emps[e] = dict(shifts=t['shifts'], paid_minutes=t['paid_minutes'],
                           overtime_minutes=t['overtime_minutes'], night_minutes=t['night_minutes'],
                           gross=money(t['gross_c']))
        for k in ('shifts', 'paid_minutes', 'overtime_minutes', 'night_minutes'):
            T[k] += t[k]
        T['gross'] += t['gross_c']
    T['gross'] = money(T['gross'])
    with open(outp, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']},
                   'employees': out_emps, 'exceptions': exc, 'totals': T}, f, indent=1)


def night_minutes(a, b, zone):
    if b <= a:
        return 0
    d0 = datetime.fromtimestamp(a, UTC).astimezone(zone).date() - timedelta(days=1)
    d1 = datetime.fromtimestamp(b, UTC).astimezone(zone).date()
    total = 0
    d = d0
    while d <= d1:
        base = datetime(d.year, d.month, d.day)
        for h0, h1 in ((0, 6), (22, 24)):
            s = local_to_ts(base + timedelta(hours=h0), zone)
            en = local_to_ts(base + timedelta(hours=h1), zone)
            lo, hi = max(a, s), min(b, en)
            if hi > lo:
                total += hi - lo
        d += timedelta(days=1)
    return total // 60


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
